// The Switchboard page: a phone or a browser's view of this Mac, served by
// the remote port. It speaks the protocol the headset speaks, over the same
// routes, and keeps nothing the host needs: the token is an HttpOnly cookie
// the page cannot read. The page is plain DOM with text only, so agent output
// never becomes markup.
(function () {
  "use strict";

  const ROUTES = {
    info: "/api/v1/info",
    me: "/api/v1/me",
    pair: "/api/v1/pair",
    events: "/api/v1/events",
    waiting: "/api/v1/waiting",
    projects: "/api/v1/projects",
    projectSessions: "/api/v1/projects/{id}/sessions",
    session: "/api/v1/sessions/{id}",
    lastResponse: "/api/v1/sessions/{id}/last-response",
    screen: "/api/v1/sessions/{id}/screen",
    send: "/api/v1/sessions/{id}/send",
  };

  const STORE_KEY = "switchboard-host";
  const POLL_MS = 3000;
  const POLL_SOCKET_MS = 20000;
  const RETRY_MIN_MS = 5000;
  const RETRY_MAX_MS = 60000;

  const PAIR_ERRORS = {
    pairing_closed:
      "Pairing is not open on the Mac. Open the pairing window there and scan its code again.",
    wrong_code: "That code does not match. The window closes after three wrong codes.",
    wrong_key: "This is not the Mac whose code was scanned.",
    rate_limited: "Too many attempts. Wait a minute and try again.",
  };

  /** The route with its `{id}` filled in, encoded for a path. */
  function route(name, id) {
    return ROUTES[name].replace("{id}", encodeURIComponent(id === undefined ? "" : id));
  }

  /** The invite's three values from a fragment, or null when one is missing. */
  function parseInvite(hash) {
    const params = new URLSearchParams(String(hash || "").replace(/^#/, ""));
    const code = params.get("code");
    const key = params.get("key");
    const id = params.get("id");
    return code && key && id ? { code, key, id } : null;
  }

  /** The name this browser pairs under: "Safari on iPhone", else "Browser". */
  function deviceName(userAgent, touchPoints) {
    const ua = String(userAgent || "");
    let device = null;
    if (/iPhone/.test(ua)) device = "iPhone";
    else if (/iPad/.test(ua) || (/Macintosh/.test(ua) && Number(touchPoints) > 1)) device = "iPad";
    else if (/Android/.test(ua)) device = "Android";
    else if (/Macintosh|Mac OS X/.test(ua)) device = "Mac";
    else if (/Windows/.test(ua)) device = "Windows";
    else if (/Linux/.test(ua)) device = "Linux";
    if (!device) return "Browser";
    let browser = "Safari";
    if (/Edg\//.test(ua)) browser = "Edge";
    else if (/Firefox\//.test(ua)) browser = "Firefox";
    else if (/Chrome\//.test(ua)) browser = "Chrome";
    return `${browser} on ${device}`;
  }

  /**
   * What a 401 means. The host does not say "revoked": a removed device and
   * an unknown token are the same answer. `/info` needs no credential, so the
   * page compares what the host says of itself with what it stored.
   */
  function inferUnauthorized(stored, info) {
    if (!stored) {
      return { state: "unpaired", message: "" };
    }
    if (!info) {
      return { state: "unreachable", message: "Can't reach the host. Check the network, then try again." };
    }
    if (info.server_id === stored.server_id && info.spki_sha256 === stored.spki_sha256) {
      return { state: "removed", message: "This device was removed on the host. Pair again." };
    }
    return { state: "changed", message: "The host's identity changed. Pair again." };
  }

  /** Whether `incoming` moves the page forward: a new epoch always does, else a revision not behind. */
  function isNewer(applied, incoming) {
    if (!incoming) return false;
    if (!applied) return true;
    if (applied.epoch !== incoming.epoch) return true;
    return incoming.revision >= applied.revision;
  }

  function sameStamp(a, b) {
    return Boolean(a && b && a.epoch === b.epoch && a.revision === b.revision);
  }

  /** Waiting sessions first, then by name. */
  function bySessionOrder(a, b) {
    return Number(b.waiting) - Number(a.waiting) || String(a.name).localeCompare(String(b.name));
  }

  /** Projects with a waiting session first, then by name; each with its sessions in order. */
  function arrangeList(projects, sessionsByProject) {
    const groups = projects.map((project) => {
      const sessions = (sessionsByProject[project.id] || []).slice().sort(bySessionOrder);
      return { project, sessions, waiting: sessions.some((s) => s.waiting) };
    });
    return groups.sort(
      (a, b) => Number(b.waiting) - Number(a.waiting) || String(a.project.name).localeCompare(String(b.project.name)),
    );
  }

  /** The words a waiting session carries: the state, and the reason in words. */
  function waitingLabel(session) {
    if (!session.waiting) return "";
    return session.waiting_reason ? `Waiting on you: ${session.waiting_reason}` : "Waiting on you";
  }

  /** How long ago a millisecond time was, in words. */
  function ago(ms, now) {
    if (!ms) return "";
    const secs = Math.max(0, Math.round((now - ms) / 1000));
    if (secs < 60) return "just now";
    const mins = Math.round(secs / 60);
    if (mins < 60) return `${mins} min ago`;
    const hours = Math.round(mins / 60);
    if (hours < 48) return `${hours} h ago`;
    return `${Math.round(hours / 24)} days ago`;
  }

  /** A random operation id, 32 hex characters, for a send that may be retried. */
  function newOp() {
    const bytes = new Uint8Array(16);
    globalThis.crypto.getRandomValues(bytes);
    return Array.from(bytes, (b) => b.toString(16).padStart(2, "0")).join("");
  }

  function pairErrorText(code, message) {
    return PAIR_ERRORS[code] || message || "Pairing failed.";
  }

  const api = {
    ROUTES,
    route,
    parseInvite,
    deviceName,
    inferUnauthorized,
    isNewer,
    sameStamp,
    arrangeList,
    waitingLabel,
    ago,
    newOp,
    pairErrorText,
  };
  if (typeof module !== "undefined" && module.exports) {
    module.exports = api;
  }

  if (typeof document === "undefined") {
    return;
  }

  // --- the page

  const state = {
    stored: null,
    me: null,
    list: null,
    session: null,
    draft: "",
    pending: null,
    view: "start",
    stopped: false,
    socket: null,
    socketOpen: false,
    retryMs: RETRY_MIN_MS,
    timer: null,
  };

  const view = () => document.getElementById("view");

  function el(tag, attrs, children) {
    const node = document.createElement(tag);
    for (const [name, value] of Object.entries(attrs || {})) {
      node.setAttribute(name, value);
    }
    for (const child of [].concat(children === undefined ? [] : children)) {
      node.append(child);
    }
    return node;
  }

  function button(label, className, onClick) {
    const node = el("button", { type: "button", class: className || "" }, label);
    node.addEventListener("click", onClick);
    return node;
  }

  function render(nodes) {
    view().replaceChildren(...nodes);
  }

  function notice(text, warn) {
    const node = document.getElementById("notice");
    node.textContent = text || "";
    node.className = warn ? "notice warn" : "notice";
    node.hidden = !text;
  }

  function setWho() {
    const host = document.getElementById("host");
    const who = document.getElementById("who");
    if (state.me) {
      host.textContent = state.me.server_name;
      who.textContent = `This device: ${state.me.name} · ${state.me.scope}`;
    } else {
      host.textContent = "Switchboard";
      who.textContent = "";
    }
  }

  function loadStored() {
    try {
      const value = JSON.parse(localStorage.getItem(STORE_KEY) || "null");
      return value && value.server_id && value.spki_sha256 ? value : null;
    } catch (error) {
      return null;
    }
  }

  function saveStored(value) {
    try {
      localStorage.setItem(STORE_KEY, JSON.stringify(value));
    } catch (error) {
      // Private browsing may refuse storage; the page still works this visit.
    }
  }

  /** One request: the status, the envelope's body, its stamp, and the refusal code. */
  async function call(method, path, body) {
    const init = { method, cache: "no-store", credentials: "same-origin", headers: {} };
    if (body !== undefined) {
      init.headers["Content-Type"] = "application/json";
      init.body = JSON.stringify(body);
    }
    let response;
    try {
      response = await fetch(path, init);
    } catch (error) {
      return { ok: false, network: true, status: 0, body: null, stamp: null, code: "", message: "" };
    }
    let json = null;
    try {
      json = await response.json();
    } catch (error) {
      json = null;
    }
    const failure = json && json.error ? json.error : null;
    return {
      ok: response.ok,
      network: false,
      status: response.status,
      body: json ? json.body : null,
      stamp: json && json.epoch !== undefined ? { epoch: json.epoch, revision: json.revision } : null,
      code: failure ? failure.code : "",
      message: failure ? failure.message : "",
    };
  }

  /** A 401 from any call: ask `/info` what it means, and stop polling until the owner pairs again. */
  async function unauthorized() {
    const info = await call("GET", ROUTES.info);
    const verdict = inferUnauthorized(state.stored, info.ok ? info.body : null);
    state.stopped = true;
    state.socketOpen = false;
    return showStart(verdict.message);
  }

  function showStart(message) {
    state.view = "start";
    setWho();
    notice(message, Boolean(message));
    render([
      el("h2", {}, "Not paired"),
      el(
        "p",
        {},
        "On the Mac, open Switchboard's Remote devices, choose Allow pairing, and scan the code with this device.",
      ),
      el("div", { class: "actions" }, [button("Try again", "", boot)]),
    ]);
  }

  async function boot() {
    state.stopped = false;
    const invite = parseInvite(location.hash);
    if (location.hash) {
      history.replaceState(null, "", location.pathname);
    }
    state.stored = loadStored();
    if (invite) {
      return pairWith(invite);
    }
    const me = await call("GET", ROUTES.me);
    if (me.status === 401) {
      return unauthorized();
    }
    if (!me.ok) {
      return showStart("Can't reach the host. Check the network, then try again.");
    }
    state.me = me.body;
    return showList();
  }

  /** Pair from an invite: check the host's key and id against it, then ask for the cookie. */
  async function pairWith(invite) {
    notice("Checking the host…", false);
    const info = await call("GET", ROUTES.info);
    if (!info.ok) {
      return showStart("Can't reach the host. Check the network, then try again.");
    }
    if (info.body.spki_sha256 !== invite.key || info.body.server_id !== invite.id) {
      return showStart("This address is a different Switchboard than the code was for. Nothing was sent.");
    }
    const paired = await call("POST", ROUTES.pair, {
      code: invite.code,
      spki_sha256: invite.key,
      device_name: deviceName(navigator.userAgent, navigator.maxTouchPoints),
      transport: "cookie",
    });
    if (!paired.ok) {
      return showStart(pairErrorText(paired.code, paired.message));
    }
    state.stored = {
      server_id: info.body.server_id,
      spki_sha256: info.body.spki_sha256,
      server_name: info.body.server_name,
    };
    saveStored(state.stored);
    const me = await call("GET", ROUTES.me);
    if (me.ok) {
      state.me = me.body;
    }
    return showList();
  }

  /** The list's data: waiting first to stamp it, then every project's sessions. */
  async function loadList() {
    const waiting = await call("GET", ROUTES.waiting);
    if (waiting.status === 401) {
      await unauthorized();
      return false;
    }
    if (!waiting.ok) {
      notice("Can't reach the host. Check the network, then try again.", true);
      return false;
    }
    const projects = await call("GET", ROUTES.projects);
    if (projects.status === 401) {
      await unauthorized();
      return false;
    }
    if (!projects.ok) {
      notice(projects.message || "The host did not list its projects.", true);
      return false;
    }
    const sessionsByProject = {};
    for (const project of projects.body.projects) {
      const page = await call("GET", route("projectSessions", project.id));
      if (page.status === 401) {
        await unauthorized();
        return false;
      }
      if (page.ok) {
        sessionsByProject[project.id] = page.body.sessions;
      }
    }
    state.list = {
      stamp: waiting.stamp,
      groups: arrangeList(projects.body.projects, sessionsByProject),
    };
    return true;
  }

  async function showList() {
    state.view = "list";
    setWho();
    if (!(await loadList())) {
      return;
    }
    renderList();
    openSocket();
    schedule();
  }

  function renderList() {
    setWho();
    const nodes = [];
    if (state.list.groups.length === 0) {
      nodes.push(el("p", { class: "meta" }, "The host has no project yet."));
    }
    for (const group of state.list.groups) {
      nodes.push(el("h2", {}, group.project.name));
      if (group.sessions.length === 0) {
        nodes.push(el("p", { class: "meta" }, "No sessions."));
        continue;
      }
      nodes.push(
        el(
          "ul",
          { class: "rows" },
          group.sessions.map((session) => el("li", {}, [sessionRow(session)])),
        ),
      );
    }
    render(nodes);
  }

  function sessionRow(session) {
    const children = [];
    if (session.waiting) {
      children.push(el("span", { class: "waiting" }, waitingLabel(session)));
    }
    children.push(el("div", { class: "name" }, session.name));
    const facts = [session.kind, session.card, ago(session.last_activity_ms, Date.now())];
    children.push(el("div", { class: "meta" }, facts.filter(Boolean).join(" · ")));
    const row = button("", "row", () => openSession(session.id));
    row.replaceChildren(...children);
    return row;
  }

  async function openSession(id) {
    state.view = "session";
    state.session = { id, view: null, stamp: null, content: null };
    state.draft = "";
    const session = await call("GET", route("session", id));
    if (session.status === 401) {
      return unauthorized();
    }
    if (!session.ok) {
      state.session = null;
      state.view = "list";
      notice(session.message || "That session is gone.", true);
      return renderList();
    }
    state.session.view = session.body.session;
    await loadContent();
    renderSession();
  }

  /** The last response of a Claude Code session, else the screen; a reply older than the one held is dropped. */
  async function loadContent() {
    const current = state.session;
    const name = current.view.kind === "claude" ? "lastResponse" : "screen";
    const reply = await call("GET", route(name, current.id));
    if (reply.status === 401) {
      return unauthorized();
    }
    if (!reply.ok) {
      return;
    }
    if (isNewer(current.stamp, reply.stamp)) {
      current.stamp = reply.stamp;
      current.content = reply.body;
    }
  }

  function renderSession() {
    const current = state.session;
    const session = current.view;
    const nodes = [button("Back to the list", "", backToList)];
    nodes.push(el("h2", {}, session.name));
    nodes.push(el("p", { class: "meta" }, `${session.kind} · ${session.card}`));
    if (session.waiting) {
      nodes.push(el("p", { class: "notice warn" }, waitingLabel(session)));
    }
    if (session.trust_question) {
      nodes.push(el("p", { class: "notice" }, "Claude Code is asking whether to trust this folder. Answer it on the Mac."));
    }
    const content = current.content;
    if (content) {
      const text = content.text || (session.kind === "claude" ? "No response yet." : "The screen is empty.");
      nodes.push(
        session.kind === "claude"
          ? el("div", { class: "response" }, text)
          : el("pre", { class: "screen" }, text),
      );
      if (content.truncated) {
        nodes.push(el("p", { class: "meta" }, "Cut short by the host's limit."));
      }
    }
    if (session.prompt_refusal) {
      nodes.push(el("p", { class: "notice" }, session.prompt_refusal));
    } else if (state.me && state.me.scope === "control") {
      nodes.push(replyBox());
    } else {
      nodes.push(el("p", { class: "meta" }, "This device reads only. Raise its scope on the Mac to send."));
    }
    render(nodes);
  }

  function replyBox() {
    const field = el("textarea", { "aria-label": "Message to the session" }, "");
    field.value = state.draft;
    field.addEventListener("input", () => {
      state.draft = field.value;
    });
    const send = button("Send", "primary", () => sendReply(field, send));
    return el("div", {}, [field, el("div", { class: "actions" }, [send])]);
  }

  function backToList() {
    state.session = null;
    state.view = "list";
    if (state.list) {
      renderList();
    }
    refreshAll();
  }

  /**
   * Send the reply. The operation id is kept until the host gives a
   * definite answer, so a retry after a dropped reply repeats the same
   * operation, which the host answers from its log rather than typing twice.
   */
  async function sendReply(field, send) {
    const text = field.value.trim();
    if (!text) {
      return;
    }
    const current = state.session;
    if (!state.pending || state.pending.session !== current.id || state.pending.text !== text) {
      state.pending = { session: current.id, text, op: newOp() };
    }
    const pending = state.pending;
    send.disabled = true;
    const reply = await call("POST", route("send", current.id), { op: pending.op, text: pending.text });
    send.disabled = false;
    if (reply.status === 401) {
      return unauthorized();
    }
    if (reply.network || reply.status >= 500 || reply.code === "interrupted") {
      notice(
        reply.code === "interrupted"
          ? "The host started this message and its outcome is unknown. Check the session before sending again."
          : "Not sent yet. Send again to retry the same message.",
        true,
      );
      return;
    }
    state.pending = null;
    if (reply.ok) {
      state.draft = "";
      field.value = "";
      notice("Sent. The session's card shows its progress.", false);
      await loadContent();
      return renderSession();
    }
    if (reply.code === "scope") {
      const me = await call("GET", ROUTES.me);
      if (me.ok) {
        state.me = me.body;
      }
    }
    notice(reply.message || "Not sent.", true);
    renderSession();
  }

  /** The list is re-read when the host's revision or epoch moves; the open session with it. */
  async function refreshAll() {
    if (state.stopped || !state.list) {
      return;
    }
    if (!(await loadList())) {
      return;
    }
    if (state.session) {
      const id = state.session.id;
      const session = await call("GET", route("session", id));
      if (session.status === 401) {
        return unauthorized();
      }
      if (session.ok) {
        state.session.view = session.body.session;
        await loadContent();
        return renderSession();
      }
      state.session = null;
      state.view = "list";
    }
    renderList();
  }

  async function refresh() {
    if (state.stopped || !state.list) {
      return;
    }
    const waiting = await call("GET", ROUTES.waiting);
    if (waiting.status === 401) {
      return unauthorized();
    }
    if (!waiting.ok || sameStamp(state.list.stamp, waiting.stamp) || !isNewer(state.list.stamp, waiting.stamp)) {
      return;
    }
    return refreshAll();
  }

  function schedule(ms) {
    clearTimeout(state.timer);
    if (state.stopped) {
      return;
    }
    const delay = ms || (state.socketOpen ? POLL_SOCKET_MS : POLL_MS);
    state.timer = setTimeout(async () => {
      if (!document.hidden) {
        await refresh();
      }
      schedule();
    }, delay);
  }

  /**
   * The events socket makes a change arrive at once where the browser allows
   * it. A failed handshake says nothing to the page, so a close is treated as
   * a reason to read again and to try once more after a doubling wait.
   */
  function openSocket() {
    if (state.stopped || state.socket || typeof WebSocket === "undefined") {
      return;
    }
    let socket;
    try {
      socket = new WebSocket(`wss://${location.host}${ROUTES.events}`);
    } catch (error) {
      return retrySocket();
    }
    state.socket = socket;
    socket.addEventListener("open", () => {
      state.socketOpen = true;
      state.retryMs = RETRY_MIN_MS;
      schedule();
    });
    socket.addEventListener("message", (event) => {
      let frame = null;
      try {
        frame = JSON.parse(event.data);
      } catch (error) {
        return;
      }
      if (frame && (frame.type === "changed" || frame.type === "resync_required")) {
        refreshAll();
      }
    });
    // An error is followed by a close, so the first of the two ends it.
    socket.addEventListener("close", () => {
      if (state.socket !== socket) {
        return;
      }
      state.socket = null;
      state.socketOpen = false;
      schedule();
      refreshAll();
      retrySocket();
    });
    socket.addEventListener("error", () => socket.close());
  }

  function retrySocket() {
    if (state.stopped) {
      return;
    }
    setTimeout(openSocket, state.retryMs);
    state.retryMs = Math.min(state.retryMs * 2, RETRY_MAX_MS);
  }

  document.addEventListener("visibilitychange", () => {
    if (!document.hidden && state.list) {
      refresh();
    }
  });

  boot();
})();

