+        let address = rest[..<hash].trimmingCharacters(in: CharacterSet(charactersIn: "/"))
+        var values: [String: String] = [:]
+        for pair in rest[rest.index(after: hash)...].split(separator: "&") {
+            let parts = pair.split(separator: "=", maxSplits: 1).map(String.init)
+            if parts.count == 2 { values[parts[0]] = parts[1] }
+        }
+        guard let code = values["code"], !code.isEmpty,
+            let key = values["key"], let id = values["id"]
+        else { throw notAnInvite }
+        return PairingInvite(
+            serverID: ServerID(id), spkiSha256: key, code: code, addresses: [address])
     }
 }
